-- Шаблоны ролей группы (src/features/roles/role-presets.ts) во всех существующих проектах.
--
-- Схема: у роли появляется необязательный ключ шаблона "presetKey" (уникален в проекте).
-- Данные: в каждый проект добавляются 9 обычных (не системных) ролей. Уже созданные роли, их
-- права и участники не меняются. Если в проекте уже есть роль с таким же названием (без пробелов
-- по краям, без регистра, ё = е), шаблон не добавляется, а в журнал проекта пишется, что он
-- пропущен и почему. Каждая добавленная роль тоже записывается в журнал (от имени владельца
-- проекта). Права в VALUES собраны из role-presets.ts; совпадение проверяет role-presets.test.ts.

-- AlterTable
ALTER TABLE "ProjectRoleDefinition" ADD COLUMN     "presetKey" TEXT;

-- CreateIndex
CREATE UNIQUE INDEX "ProjectRoleDefinition_projectId_presetKey_key" ON "ProjectRoleDefinition"("projectId", "presetKey");

-- Data
