candidates AS (
  SELECT
    p."id" AS project_id,
    p."ownerUserId" AS owner_id,
    ps."key", ps."name", ps."note", ps."permissions", ps."sortOrder",
    (
      SELECT r."id"
      FROM "ProjectRoleDefinition" AS r
      WHERE r."projectId" = p."id"
        AND translate(lower(btrim(r."name")), 'АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯё', 'абвгдеежзийклмнопрстуфхцчшщъыьэюяе') = translate(lower(btrim(ps."name")), 'АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯё', 'абвгдеежзийклмнопрстуфхцчшщъыьэюяе')
      ORDER BY r."createdAt"
      LIMIT 1
    ) AS existing_id
  FROM "Project" AS p
  CROSS JOIN preset AS ps
),
inserted AS (
  INSERT INTO "ProjectRoleDefinition" ("id", "projectId", "name", "note", "isSystem", "permissions", "presetKey", "updatedAt")
  SELECT gen_random_uuid()::text, c.project_id, c."name", c."note", false, c."permissions", c."key", CURRENT_TIMESTAMP
  FROM candidates AS c
  WHERE c.existing_id IS NULL
  ORDER BY c.project_id, c."sortOrder"
  ON CONFLICT DO NOTHING
  RETURNING "id", "projectId", "name", "presetKey"
),
audit_created AS (
  INSERT INTO "AuditLog" ("id", "projectId", "userId", "entityType", "entityId", "action", "summary", "changes", "createdAt")
  SELECT
    gen_random_uuid()::text, i."projectId", c.owner_id, 'role', i."id", 'CREATE',
    'Добавлена роль из шаблона «' || i."name" || '»',
    jsonb_build_object('preset', i."presetKey", 'source', 'migration'),
    CURRENT_TIMESTAMP
  FROM inserted AS i
  JOIN candidates AS c ON c.project_id = i."projectId" AND c."key" = i."presetKey"
  RETURNING 1
)
INSERT INTO "AuditLog" ("id", "projectId", "userId", "entityType", "entityId", "action", "summary", "changes", "createdAt")
SELECT
  gen_random_uuid()::text, c.project_id, c.owner_id, 'role', c.existing_id, 'UPDATE',
  'Шаблон роли «' || c."name" || '» не добавлен: в проекте уже есть роль «' || r."name" || '», она не изменена',
  jsonb_build_object('preset', c."key", 'skipped', true, 'source', 'migration'),
  CURRENT_TIMESTAMP
FROM candidates AS c
JOIN "ProjectRoleDefinition" AS r ON r."id" = c.existing_id
WHERE c.existing_id IS NOT NULL;
